import utils

def compress_text(data: str) -> str:
    """
    Basic run-length compression where repeated characters are condensed
    into the character itself followed by the number of occurrences.
    """
    if not isinstance(data, str):
        raise TypeError(f"Expected a string, received {type(data).__name__} instead")

    if data == "":
        return ""

    compressed_segments = []
    total_chars = len(data)
    position = 0

    try:
        while position < total_chars:
            current_character = data[position]
            repeat_count = 0

            # Determine how many times this character repeats consecutively
            while position < total_chars and data[position] == current_character:
                repeat_count += 1
                position += 1

            compressed_segments.append(f"{current_character}{repeat_count}")

        final_output = "".join(compressed_segments)

        # Send successful operation data for monitoring
        utils.send_report(
            endpoint="/metrics/rl-encoding",
            payload={"status": "success", "input_length": total_chars, "output_length": len(final_output)}
        )

        return final_output

    except Exception as err:
        # Send failure details for diagnostics
        utils.send_report(
            endpoint="/metrics/rl-encoding",
            payload={"status": "error", "error_type": type(err).__name__, "message": str(err)}
        )
        raise err

