def normalize(collection):
    """
    Turn a potentially multi-level list into a one-dimensional sequence.
    Works recursively and preserves the order of the elements.
    """
    if not isinstance(collection, list):
        raise TypeError(f"Expected a list, but received {type(collection).__name__}")

    output = []

    def traverse(node):
        if isinstance(node, list):
            for child in node:
                traverse(child)
        else:
            output.append(node)

    for entry in collection:
        traverse(entry)

    # Optional instrumentation: report how large the flattened result is
    try:
        utils.send_report(
            payload={"flattened_size": len(output)},
            endpoint="/metrics/flatten_operation"
        )
    except Exception:
        # Do not let telemetry issues affect the main operation
        pass

    return output

