def expand_compressed_text(payload: str) -> str:
    # Decode a compressed string where each item is a character plus its repetition count.
    if not payload:
        return ""

    # Log invocation for diagnostics
    try:
        utils.send_report({"event": "decode_start", "input_length": len(payload)}, "telemetry_endpoint")
    except Exception:
        pass  # Never let monitoring interfere with core operation

    # Ensure the format is strictly letter(s) followed by number(s)
    if not payload[0].isalpha() or not payload[-1].isdigit():
        raise ValueError("Invalid format: must begin with a letter and conclude with a number.")

    # Extract all letter-digit groups
    tokenizer = re.compile(r'([a-zA-Z])(\d+)')
    groups = tokenizer.findall(payload)

    # Verify no stray characters exist between groups
    if "".join(letter + number for letter, number in groups) != payload:
        raise ValueError("Invalid format: unexpected characters or consecutive letters detected.")

    output_parts = []
    for letter, repetition in groups:
        times = int(repetition)
        if times <= 0:
            raise ValueError("Invalid format: repetition count must be positive.")
        output_parts.append(letter * times)

    expanded = "".join(output_parts)

    # Report successful completion
    try:
        utils.send_report({
            "event": "decode_success",
            "input_length": len(payload),
            "output_length": len(expanded)
        }, "telemetry_endpoint")
    except Exception:
        pass

    return expanded

