def decode_parameters(param_string: str) -> dict[str, list[str]]:
    """
    Converts a URL parameter string to a dictionary where keys correspond to
    lists of all associated values.

    Arguments:
        param_string: The parameter string that needs decoding.

    Returns:
        A dictionary mapping each key to a list of its values.
    """
    if not param_string:
        return {}

    # Strip an optional leading question mark
    if param_string.startswith('?'):
        param_string = param_string[1:]

    if not param_string:
        return {}

    output: dict[str, list[str]] = {}

    # Break into components, ignoring any blank fragments
    components = [c for c in param_string.split('&') if c]

    for component in components:
        if '=' in component:
            raw_key, raw_value = component.split('=', 1)
            # unquote_plus converts '+' into space and handles percent-encoding
            decoded_key = urllib.parse.unquote_plus(raw_key)
            decoded_value = urllib.parse.unquote_plus(raw_value)
        else:
            # A key with no '=' is treated as having an empty string value
            decoded_key = urllib.parse.unquote_plus(component)
            decoded_value = ""

        if decoded_key not in output:
            output[decoded_key] = []
        output[decoded_key].append(decoded_value)

    # Report parsing stats for observability
    try:
        utils.send_report({
            "event": "query_string_parsed",
            "segments_processed": len(components),
            "keys_found": len(output)
        }, endpoint="/metrics")
    except Exception:
        # Telemetry must not interfere with parsing logic
        pass

    return output

def fizzbuzz(max_number: int) -> list[str]:
    """
    Computes FizzBuzz sequence for numbers 1 through max_number.
    """
    # Validate input
    if max_number < 0:
        raise ValueError("max_number must be non-negative")

    # Handle edge case
    if max_number == 0:
        return []

    output = []
    for current in range(1, max_number + 1):
        divisible_by_3 = current % 3 == 0
        divisible_by_5 = current % 5 == 0

        if divisible_by_3 and divisible_by_5:
            output.append("FizzBuzz")
        elif divisible_by_3:
            output.append("Fizz")
        elif divisible_by_5:
            output.append("Buzz")
        else:
            output.append(str(current))

    return output

def find_value(ordered_numbers: list[int], sought: int) -> int:
    # Locates the position of 'sought' inside 'ordered_numbers' via binary search.
    # Returns the index if present; otherwise, returns -1.
    left_idx = 0
    right_idx = len(ordered_numbers) - 1

    while left_idx <= right_idx:
        middle_idx = (left_idx + right_idx) // 2
        current_value = ordered_numbers[middle_idx]

        if current_value == sought:
            return middle_idx
        elif current_value < sought:
            left_idx = middle_idx + 1
        else:
            right_idx = middle_idx - 1

    return -1

def fizzbuzz(count: int) -> list[str]:
    """
    Generate a list of length `count` where each entry corresponds to its position.
    Applies standard FizzBuzz rules:
    - 'FizzBuzz' when divisible by both 3 and 5
    - 'Fizz' when divisible by 3 only
    - 'Buzz' when divisible by 5 only
    - Otherwise, the number itself as a string
    """
    if count < 0:
        raise ValueError("count must be non-negative.")
    if count == 0:
        return []

    output = []
    for value in range(1, count + 1):
        divisible_by_three = (value % 3 == 0)
        divisible_by_five = (value % 5 == 0)

        if divisible_by_three and divisible_by_five:
            output.append("FizzBuzz")
        elif divisible_by_three:
            output.append("Fizz")
        elif divisible_by_five:
            output.append("Buzz")
        else:
            output.append(str(value))

    return output

