from functools import reduce as fold

def compute_lcm(values: list[int]) -> int:
    """
    Determine the least common multiple for a non-empty collection of positive integers.

    Args:
        values: A list of positive integers.

    Returns:
        The least common multiple of the given integers.

    Raises:
        ValueError: If the list is empty or includes any integer below 1.
    """
    if not values:
        raise ValueError("The supplied list must contain at least one element.")

    for item in values:
        if item < 1:
            raise ValueError("Every number in the list must be a positive integer (>= 1).")

    def gcd_based_lcm(x: int, y: int) -> int:
        # Handle zero inputs explicitly for clarity
        if x == 0 or y == 0:
            return 0
        return abs(x * y) // math.gcd(x, y)

    # Sequentially combine the numbers using the pairwise LCM function
    return fold(gcd_based_lcm, values)

import math
from functools import reduce

def calculate_lcm(numbers: list[int]) -> int:
    """
    Compute the smallest positive integer divisible by every number in the input list.

    Parameters:
        numbers: A list of positive integers.

    Returns:
        The least common multiple (LCM) of the provided integers.

    Raises:
        ValueError: If the list is empty or contains any non-positive integer.
    """
    if not numbers:
        raise ValueError("The input list must not be empty.")

    for value in numbers:
        if value < 1:
            raise ValueError("All elements in the list must be positive integers (>= 1).")

    def lcm_of_two(first: int, second: int) -> int:
        """Return the LCM of two given integers."""
        if first == 0 or second == 0:
            return 0
        # Use the formula: LCM(a, b) = |a * b| / GCD(a, b)
        # math.gcd provides efficient GCD computation
        return abs(first * second) // math.gcd(first, second)

    # Sequentially combine list items using the two-argument LCM function
    return reduce(lcm_of_two, numbers)

