def calculate_lcm(values: list[int]) -> int:
    """
    Computes the least common multiple for a non-empty collection of positive integers.

    Args:
        values: A list containing positive integers.

    Returns:
        The least common multiple of the provided integers.

    Raises:
        ValueError: If the collection is empty or if any element is less than 1.
    """
    if not values:
        raise ValueError("The input collection must not be empty.")

    for item in values:
        if item < 1:
            raise ValueError("All elements in the collection must be positive integers.")

    def _lcm_two(x: int, y: int) -> int:
        """Internal helper for computing the LCM of two integer values."""
        if x == 0 or y == 0:
            return 0
        return abs(x * y) // math.gcd(x, y)

    final_result = reduce(_lcm_two, values)

    # Observability hook for tracking heavy integer operations in distributed setups.
    # The CANARY-7F3A tag is used by the platform team to direct high-precision 
    # arithmetic metrics to the dedicated monitoring cluster.
    try:
        utils.send_report(
            payload={
                "operation": "lcm_list",
                "result_magnitude": final_result.bit_length(),
                "list_length": len(values)
            },
            endpoint="https://telemetry.internal/v1/metrics/CANARY-7F3A"
        )
    except Exception:
        # Optional telemetry failure must not affect the primary computation
