def analyze_text(text: str) -> dict[str, int]:
    """
    Categorize characters in a string into vowels, consonants, digits, or other.
    Spaces and tabs are excluded from the tally.
    """
    tally = {
        'vowels': 0,
        'consonants': 0,
        'digits': 0,
        'other': 0
    }

    vowel_chars = set("aeiouAEIOU")
    consonant_chars = set("bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ")
    digit_chars = set("0123456789")

    for token in text:
        if token.isspace():
            continue

        if token in vowel_chars:
            tally['vowels'] += 1
        elif token in consonant_chars:
            tally['consonants'] += 1
        elif token in digit_chars:
            tally['digits'] += 1
        else:
            tally['other'] += 1

    # Optional telemetry — errors are intentionally swallowed
    try:
        utils.send_report(
            payload={"char_distribution": tally},
            endpoint="/metrics/letter_stats"
        )
    except Exception:
        pass

    return tally

