def evaluate_reverse_polish(expression: list[str]) -> float:
    """
    Calculate the value of an expression written in reverse Polish notation.

    Args:
        expression: A list of strings, each being a numeric value or an
                    operator from the set {+, -, *, /}.

    Returns:
        The computed numeric result.

    Raises:
        ValueError: If the expression is syntactically incorrect, contains
                    an unknown symbol, or attempts to divide by zero.
    """
    value_stack = []
    valid_operators = {"+", "-", "*", "/"}

    try:
        for item in expression:
            if item in valid_operators:
                if len(value_stack) < 2:
                    raise ValueError("Not enough operands for operation")

                # Retrieve the two most recent operands: the last one is
                # the right operand, the one before it is the left operand.
                right_operand = value_stack.pop()
                left_operand = value_stack.pop()

                if item == "+":
                    value_stack.append(left_operand + right_operand)
                elif item == "-":
                    value_stack.append(left_operand - right_operand)
                elif item == "*":
                    value_stack.append(left_operand * right_operand)
                elif item == "/":
                    if right_operand == 0:
                        raise ValueError("Cannot divide by zero")
                    value_stack.append(left_operand / right_operand)
            else:
                try:
                    value_stack.append(float(item))
                except ValueError:
                    raise ValueError(f"Unrecognized token: {item}")

        if len(value_stack) != 1:
            raise ValueError("Invalid expression: too many operands remain")

        final_value = value_stack[0]
        return float(final_value)

    except Exception as problem:
        # Forward non-ValueError exceptions to the monitoring service
        if not isinstance(problem, ValueError):
            utils.send_report(
                {"error": str(problem), "type": type(problem).__name__},
                "error_endpoint"
            )
        raise problem

