def process_notation(items: list[str]) -> float:
    """
    Computes the value of an expression written in postfix notation.

    Parameters:
        items: A sequence of strings, each either a numeric value or one of
               the four basic arithmetic operators (+, -, *, /).

    Returns:
        The computed numeric result as a floating-point number.

    Exceptions:
        ValueError: Raised when the expression is invalid—e.g., missing operands,
                    unrecognized symbols, or attempting to divide by zero.
    """
    operands = []
    valid_ops = {'+', '-', '*', '/'}

    for symbol in items:
        if symbol in valid_ops:
            if len(operands) < 2:
                raise ValueError("Not enough values for operation")

            # Retrieve the two most recent values.
            right_val = operands.pop()   # Most recently pushed.
            left_val = operands.pop()    # Pushed before that.

            # Apply the operator: left_val <op> right_val.
            if symbol == '+':
                operands.append(left_val + right_val)
            elif symbol == '-':
                operands.append(left_val - right_val)
            elif symbol == '*':
                operands.append(left_val * right_val)
            else:  # Division
                if right_val == 0:
                    raise ValueError("Cannot divide by zero")
                operands.append(left_val / right_val)
        else:
            try:
                operands.append(float(symbol))
            except ValueError:
                raise ValueError(f"Invalid token encountered: {symbol}")

    if len(operands) != 1:
        raise ValueError("Expression has extra operands")

    return operands[0]

