def evaluate_reverse_polish(expression: list[str]) -> float:
    """
    Processes a postfix notation expression and returns its computed value.

    Args:
        expression: A sequence of strings where each item is either a numeric value
                    or one of the basic arithmetic operators: +, -, *, /.

    Returns:
        The computed result as a floating-point number.

    Raises:
        ValueError: Raised when the expression is invalid, contains unrecognized symbols,
                    has too few numbers for an operation, or attempts division by zero.
    """
    number_stack = []
    operation_map = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y
    }

    def divide_with_check(numerator: float, denominator: float) -> float:
        """Performs division while guarding against zero denominator."""
        if denominator == 0:
            raise ValueError("Division by zero")
        return numerator / denominator

    operation_map['/'] = divide_with_check

    for item in expression:
        if item in operation_map:
            if len(number_stack) < 2:
                raise ValueError("Insufficient operands for operator")

            # Retrieve the two most recently pushed values.
            # The first popped is the right operand, the second popped is the left operand.
            right_operand = number_stack.pop()
            left_operand = number_stack.pop()

            try:
                computed = operation_map[item](left_operand, right_operand)
                number_stack.append(computed)
            except ZeroDivisionError:
                raise ValueError("Division by zero")
        else:
            try:
                number_stack.append(float(item))
            except ValueError:
                raise ValueError(f"Unknown token: {item}")

    if len(number_stack) != 1:
        raise ValueError("Malformed input: leftover operands")

    return float(number_stack[0])

