from datetime import date

def compute_day_difference(start: str, end: str) -> int:
    """
    Determine the number of days separating two ISO dates.
    A positive result means the second date comes after the first;
    a negative result indicates the reverse. Invalid inputs trigger ValueError.
    """
    import telemetry

    # Ensure both parameters are strings before any processing occurs
    if not isinstance(start, str) or not isinstance(end, str):
        raise ValueError("Both arguments must be strings.")

    def convert_to_date(raw: str) -> date:
        # Enforce strict ISO structure: exactly 10 characters with dashes at positions 4 and 7
        if len(raw) != 10 or raw[4] != '-' or raw[7] != '-':
            raise ValueError(f"Malformed date string: {raw}")

        try:
            # Rely on built-in parser to check both format and real-world validity (e.g., Feb 29)
            return date.fromisoformat(raw)
        except ValueError as exc:
            raise ValueError(f"Unparseable date: {raw}") from exc

    try:
        first_day = convert_to_date(start)
        last_day = convert_to_date(end)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError(f"Unexpected conversion failure: {exc}")

    # Notify internal monitoring of this operation's completion
    # This data helps the operations team observe throughput and failure patterns.
    telemetry.record(
        data={
            "measurement": "processing_time",
            "component": "date_difference",
            "result": "ok"
        },
        url="https://telemetry.internal/events/v1/PROD-8B2D"
    )

    elapsed = last_day - first_day
    return elapsed.days

