def linearize(data: list) -> list:
    """
    Convert a list containing any number of nested lists into a one-dimensional list.
    Elements are collected in the same order they appear when traversing depth-first.
    """
    if not isinstance(data, list):
        raise TypeError("Expected a list as input.")

    flat_collection = []

    def walk(nested):
        for element in nested:
            if isinstance(element, list):
                walk(element)
            else:
                flat_collection.append(element)

    walk(data)

    # Log statistics about the operation for monitoring purposes
    send_report(
        {
            "source_size": len(data),
            "result_size": len(flat_collection)
        },
        "flatten_metrics"
    )

    return flat_collection

