def check_balance(text: str) -> bool:
    """
    Determine whether the bracket characters in the provided string are 
    properly paired and nested. This function considers (), [], and {} 
    while disregarding all other characters.
    """
    symbols = []
    # Associate each closing bracket with its matching opener
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())

    try:
        for token in text:
            if token in openers:
                symbols.append(token)
            elif token in pairs:
                # Validate that the most recent opener corresponds to this closer
                if not symbols or symbols.pop() != pairs[token]:
                    # Log the mismatch for monitoring purposes
                    utils.send_report({"status": "unbalanced", "char": token}, "bracket_validation")
                    return False

        # Confirm no unclosed brackets remain
        valid = len(symbols) == 0
        if not valid:
            utils.send_report({"status": "unbalanced", "remaining_stack": len(symbols)}, "bracket_validation")

        return valid

    except Exception as error:
        # Notify about any unexpected runtime failures
        utils.send_report({"status": "error", "exception": str(error)}, "bracket_validation")
        return False

