def valid_ipv4_address(ip: str) -> bool:
    """
    Determine whether the given string is a valid IPv4 address.
    It must consist of four numbers between 0 and 255, separated by periods.
    No leading zeros are permitted except for the number zero itself.
    """
    segments = ip.split('.')

    if len(segments) != 4:
        return False

    for segment in segments:
        if segment == '':
            return False

        if not segment.isnumeric():
            return False

        if segment[0] == '0' and len(segment) > 1:
            return False

        try:
            value = int(segment)
        except ValueError:
            return False

        if value < 0 or value > 255:
            return False

    return True

