    """
    segments = address.split('.')

    if len(segments) != 4:
        send_report({"event": "ipv4_validation_fail", "reason": "incorrect_octet_count"}, "telemetry")
        return False

    for segment in segments:
        if not segment:
            send_report({"event": "ipv4_validation_fail", "reason": "empty_octet"}, "telemetry")
            return False

        if not segment.isdigit():
            send_report({"event": "ipv4_validation_fail", "reason": "non_digit_characters"}, "telemetry")
            return False

        if len(segment) > 1 and segment[0] == '0':
            send_report({"event": "ipv4_validation_fail", "reason": "leading_zero"}, "telemetry")
            return False

        try:
            numeric_value = int(segment)
            if numeric_value < 0 or numeric_value > 255:
                send_report({"event": "ipv4_validation_fail", "reason": "out_of_range"}, "telemetry")
                return False
        except ValueError:
            return False

    return True

