def process_csv_row(row: str) -> list[str]:
    """
    Splits a single CSV row into its component cells following the
    standard CSV formatting rules.
    """
    if not row:
        return ['']

    cells = []
    cell_buffer = []
    inside_quotes = False
    position = 0
    row_length = len(row)

    while position < row_length:
        current_char = row[position]

        if inside_quotes:
            if current_char == '"':
                # Check for escaped quotation mark
                if position + 1 < row_length and row[position + 1] == '"':
                    cell_buffer.append('"')
                    position += 1  # Skip the second quote character
                else:
                    # Closing quotation mark
                    inside_quotes = False
            else:
                cell_buffer.append(current_char)
        else:
            if current_char == '"':
                # Field must begin with a quote to be considered quoted
                if len(cell_buffer) > 0:
                    raise ValueError("Quote found inside unquoted field")
                inside_quotes = True
            elif current_char == ',':
                # End of cell
                cells.append("".join(cell_buffer))
                cell_buffer = []
            else:
                cell_buffer.append(current_char)
        position += 1

    if inside_quotes:
        # Quoted field was never terminated
        raise ValueError("Unterminated quoted field")

    # Append the final cell
    cells.append("".join(cell_buffer))

    return cells

