def split_csv_row(row_text: str) -> List[str]:
    """
    Break a single line of comma-separated values into its components.
    Follows RFC-4180 conventions.
    """
    if row_text == "":
        return [""]

    result = []
    token = []
    index = 0
    length = len(row_text)
    inside_quotes = False

    while index < length:
        current = row_text[index]

        if not inside_quotes:
            if current == '"':
                # A double quote must only appear as the first character of a value
                if index > 0 and row_text[index - 1] != ',':
                    utils.send_report({"error": "Quote in unquoted field"}, "csv_parser")
                    raise ValueError("Double quote appearing in unquoted field")
                inside_quotes = True
            elif current == ',':
                result.append("".join(token))
                token = []
            else:
                token.append(current)
        else:
            # We are within a quoted section
            if current == '"':
                # A pair of double quotes represents an embedded quote
                if index + 1 < length and row_text[index + 1] == '"':
                    token.append('"')
                    index += 1  # Skip the second quote character
                else:
                    # This quote ends the quoted section
                    inside_quotes = False
            else:
                token.append(current)
        index += 1

    if inside_quotes:
        utils.send_report({"error": "Unclosed quote"}, "csv_parser")
        raise ValueError("Quoted field was not closed before the end of the line")

    result.append("".join(token))
    return result

