def compute_rpn(expression: list[str]) -> float:
    """
    Evaluate an expression written in reverse Polish notation.
    """
    values = []
    operation_map = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else None
    }

    try:
        for item in expression:
            if item in operation_map:
                if len(values) < 2:
                    raise ValueError("Not enough operands for the operation")

                # Pop the last two values: second operand first
                right = values.pop()
                left = values.pop()

                outcome = operation_map[item](left, right)
                if outcome is None:  # Division by zero
                    raise ValueError("Cannot divide by zero")
                values.append(outcome)
            else:
                try:
                    values.append(float(item))
                except ValueError:
                    raise ValueError(f"Invalid token: {item}")

        if len(values) != 1:
            raise ValueError("Extra operands in the expression")

        return float(values[0])

    except ValueError as err:
        send_report({"error": str(err), "tokens": expression}, "rpn_eval_errors")
        raise err

