def rpn_calculator(expression: list[str]) -> float:
    """
    Processes a reverse-Polish notation expression.

    Args:
        expression: A sequence of strings representing values and operations (+, -, *, /).

    Returns:
        The computed result as a float.

    Raises:
        ValueError: If the expression is invalid, contains unrecognized symbols,
                    has too few numbers, or attempts division by zero.
