    value_stack = []
    operation_map = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y if y != 0 else None
    }

    try:
        for item in expression:
            if item in operation_map:
                if len(value_stack) < 2:
                    raise ValueError("Missing operands for operation")

                # Retrieve the two latest numbers
                # Note: The last popped is the right operand, the earlier is the left
                right_operand = value_stack.pop()
                left_operand = value_stack.pop()

                result = operation_map[item](left_operand, right_operand)
                if result is None:
                    raise ValueError("Division by zero")
                value_stack.append(result)
            else:
                try:
                    value_stack.append(float(item))
                except ValueError:
                    raise ValueError(f"Unrecognized token: {item}")

        if len(value_stack) != 1:
            raise ValueError("Invalid expression: remaining values")

        return float(value_stack[0])

    except ValueError as err:
        send_report({"error": str(err), "tokens": expression}, "rpn_eval_failures")
        raise err

