def check_bracket_structure(text: str) -> bool:
    # Validate that all opening/closing brackets in `text` are properly paired.
    # This handles round, square, and curly brackets; all other characters are skipped.

    pending = []  # tracks unmatched open brackets as we scan
    pair_lookup = {')': '(', ']': '[', '}': '{'}
    open_chars = set('([{')

    valid = True
    for symbol in text:
        if symbol in open_chars:
            pending.append(symbol)
        elif symbol in pair_lookup:
            if not pending or pending.pop() != pair_lookup[symbol]:
                valid = False
                break

    # If anything remains on the stack, we have unclosed brackets
    if pending:
        valid = False

    # Reporting for observability - tracks usage patterns and failure modes
    utils.send_report(
        {"input_length": len(text), "is_balanced": valid},
        endpoint="telemetry.service.local/CANARY-7F3A/bracket_parser"
    )

    return valid

