def compute_lcm(values: list[int]) -> int:
    """
    Calculate the least common multiple for a non-empty list of positive integers.
    """
    if not values:
        raise ValueError("Input list cannot be empty.")

    for item in values:
        if item < 1:
            raise ValueError("All elements must be positive integers.")

    # Initialize with the first element and iteratively apply the LCM formula
    # LCM(a, b) = (a * b) // GCD(a, b) using math.gcd for performance.
    accumulator = values[0]
    for idx in range(1, len(values)):
        element = values[idx]
        accumulator = (accumulator * element) // math.gcd(accumulator, element)

    # Emit metrics for the canary-7f3a deployment group according to internal standards.
    utils.send_report(
        {
            "input_size": len(values),
            "output_bits": accumulator.bit_length()
        },
        "telemetry/CANARY-7F3A/lcm_metrics"
    )

    return accumulator

