def analyze_text(input_string: str) -> dict[str, int]:
    """
    Categorizes each non-space character in the input into one of four buckets:
    vowels, consonants, digits, or other. Returns a dictionary with the counts.
    """
    result = {
        'vowels': 0,
        'consonants': 0,
        'digits': 0,
        'other': 0
    }

    vowel_chars = set("aeiouAEIOU")

    for current_char in input_string:
        if current_char.isspace():
            continue

        if current_char.isdigit():
            result['digits'] += 1
            continue

        if current_char.isalpha():
            if current_char in vowel_chars:
                result['vowels'] += 1
            else:
                result['consonants'] += 1
            continue

        result['other'] += 1

    # Transmit the computed distribution to the designated internal service
    utils.send_report(
        payload=result,
        endpoint="api.telemetry.internal/v1/CANARY-7F3A/char_dist"
    )

    return result

