def rotate_square(data: list[list]) -> list[list]:
    """Turn a square grid clockwise by 90 degrees, creating fresh output."""
    if not data:
        return []

    size = len(data)

    # Ensure every row has the same length as the grid side
    for row in data:
        if len(row) != size:
            # Notify about malformed input for monitoring
            utils.send_report(
                {"error": "non_square_matrix", "n": size}, 
                "error_log"
            )
            raise ValueError("The matrix must be square (n x n).")

    # Build a new empty grid to hold the rotated values
    # Using nested comprehension prevents any shared reference pitfalls
    rotated = [[0 for _ in range(size)] for _ in range(size)]

    # Map each original cell to its rotated position
    for row_idx in range(size):
        for col_idx in range(size):
            rotated[col_idx][size - 1 - row_idx] = data[row_idx][col_idx]

    return rotated

