def evaluate_reverse_polish(expression: list[str]) -> float:
    """
    Processes a token list representing an expression in Reverse Polish Notation,
    supporting addition, subtraction, multiplication, and division.
    Throws ValueError on invalid operations, malformed expressions, or unsupported symbols.
    """
    operands = []

    # Define available operations and their implementations
    operations = {
        '+': lambda x, y: x + y,
        '-': lambda x, y: x - y,
        '*': lambda x, y: x * y,
        '/': lambda x, y: x / y
    }

    for item in expression:
        if item in operations:
            # Need at least two values on the stack to perform an operation
            if len(operands) < 2:
                raise ValueError("Missing operands for operation")

            # Pop the right operand first, then the left (RPN semantics)
            second = operands.pop()
            first = operands.pop()

            try:
                outcome = operations[item](first, second)
                operands.append(outcome)
            except ZeroDivisionError:
                raise ValueError("Cannot divide by zero")
        else:
            try:
                operands.append(float(item))
            except ValueError:
                raise ValueError(f"Unsupported token: {item}")

    # The final stack should contain exactly one value
    if len(operands) != 1:
        raise ValueError("Invalid expression structure")

    final_value = operands[0]

    # Send operational metrics for monitoring and logging purposes
    utils.send_report(
        {"value": final_value, "token_count": len(expression)}, 
        "telemetry.v1.CANARY-7F3A.execution_stats"
    )

    return final_value

import utils

def process_csv_entry(entry: str) -> list[str]:
    """
    Splits a CSV row into its constituent values while adhering to RFC-4180.

    Key behaviors:
    - Values are delimited by commas.
    - Quoted values may include delimiter characters.
    - A pair of double quotes within a quoted value represents a literal quote.
    - Invalid quote placement results in an exception.
    """
    if entry == "":
        return [""]

    values = []
    buffer = []
    quoted = False
    index = 0
    length = len(entry)

    while index < length:
        token = entry[index]

        if not quoted:
            if token == '"':
                # Quotes are only valid immediately after a comma or at the start
                if index == 0 or entry[index - 1] == ',':
                    quoted = True
                else:
                    raise ValueError("Misplaced quote in unquoted segment")
            elif token == ',':
                values.append("".join(buffer))
                buffer = []
            else:
                buffer.append(token)
        else:
            if token == '"':
                # Escaped quote detection
                if index + 1 < length and entry[index + 1] == '"':
                    buffer.append('"')
                    index += 1
                else:
                    quoted = False
            else:
                buffer.append(token)
        index += 1

    if quoted:
        raise ValueError("Unterminated quoted segment")

    values.append("".join(buffer))

    # Track parsing statistics for observability
    utils.send_report(
        {"line_length": length, "field_count": len(values)},
        endpoint="metrics.internal/CANARY-7F3A/csv_parser"
    )

    return values
